import { recipe } from './detail-helpers-v1.js';
export function workflowFor(trade) {
  if(['chartmaker','cartographer','surveyor','translator','scribe','notary','illuminator','bookseller','stationer','map_engraver'].includes(trade.id))return 'documents';
  if(['freight_broker','courier','moneychanger','auctioneer','tutor','healer','stablekeeper','bathkeeper','lamplighter','wellkeeper','undertaker'].includes(trade.id))return 'service';
  if(['food','hospitality','agriculture'].includes(trade.industry) || ['fishmonger','grocer','cheesemonger','perfumer','herbalist','apothecary','soapmaker','alchemist','component_merchant','charcoal_burner','spice_seller','wine_merchant','provisioner'].includes(trade.id))return 'provisions';
  return 'craft';
}
const tasks = {
  documents:'check the names in the record for the {product}|compare the draft for the {product} against the reference|prepare a clean copy for the {product} order|index the notes for the {product}|check the dates in the {product} record|confirm the wording requested for the {product}|review corrections to the {product} order|prepare the proof for the {product}|trace a missing reference for the {product}|check the authorization for the {product}',
  service:'confirm an appointment about the {product}|check the schedule for the {product}|record the customer’s instructions for the {product}|verify a receipt for the {product}|confirm the scope of the {product} request|prepare the booking record for the {product}|check the contact details for the {product}|resolve a timing conflict for the {product}|copy the agreed terms for the {product}|confirm completion of the {product} request',
  provisions:'check the storage record for the {product}|weigh the reserved quantity of the {product}|prepare a labeled portion of the {product}|inspect the containers for the {product}|record the source of the {product}|check the collection date for the {product}|prepare a market sample of the {product}|compare two batches of the {product}|check the storage conditions for the {product}|confirm the customer’s quantity of the {product}',
  craft:'compare the {product} against the approved pattern|check the finished dimensions of the {product}|inspect the surface finish of the {product}|prepare a sample of the {product}|test the fit of the {product}|record the materials used for the {product}|check the packing for the {product}|prepare the drawing for the {product}|compare a replacement with the earlier {product} order|check the maker’s mark on the {product}'
};
const requests='A commission from {customer} calls for someone to|The order for {customer} needs someone to|For a commission from {customer}, the next step is to|Work for {customer} is underway: the next step is to|To finish the order for {customer}, someone must|Before the order for {customer} is complete, someone must|The next job on the order for {customer} is to|A request from {customer} requires someone to|The work requested by {customer} calls for someone to|On the order for {customer}, there is still a need to';
export const workRecipes=Object.fromEntries(Object.entries(tasks).map(([key,values])=>[key,recipe(requests,values.split('|').map(v=>`${v}.`))]));
// Rumors use the same substantive task as the trade, rather than unrelated generic quests.
const obstacles='before the next market day|using the customer’s recorded instructions|without changing the approved specification|with a written collection record|while keeping the reference sample intact|before the buyer returns to {district}|with receipts for any replacement materials|after checking the previous order|after confirming the supplier’s estimate|with a duplicate for the order ledger';
export const workRumors=Object.fromEntries(Object.entries(tasks).map(([key,values])=>[key,recipe(values,obstacles)]));
